#!/usr/bin/env node

/**
 * Generate node-esm.mjs from the compiled CommonJS entry.
 *
 * ESM cannot re-export dynamically, so after compile we require
 * `<dist>/node/index.js`, list every enumerable own export, and write explicit
 * `export const X = kit.X` lines (plus `export default`).
 *
 * Usage:
 *   node scripts/generate-node-esm.mjs            # reads ./dist
 *   node scripts/generate-node-esm.mjs dev-dist   # reads ./dev-dist
 * The generated file always requires `./dist/node/index.js` at runtime.
 */

import { createRequire } from 'node:module';
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const distDir = process.argv[2] || 'dist';
const require = createRequire(import.meta.url);
const kit = require(path.join(root, distDir, 'node', 'index.js'));

const skip = new Set(['default', '__esModule']);
const ident = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const keys = Object.keys(kit)
  .filter((k) => !skip.has(k) && ident.test(k))
  .sort();

const lines = [
  '/**',
  ' * ESM entry for `neozipkit/node`.',
  ' * GENERATED by scripts/generate-node-esm.mjs — do not edit by hand.',
  ' * The compiled kit is CommonJS; Node does not surface its getter exports as named ESM imports.',
  ' */',
  'import { createRequire } from "node:module";',
  '',
  'const require = createRequire(import.meta.url);',
  'const kit = require("./dist/node/index.js");',
  '',
  ...keys.map((k) => `export const ${k} = kit.${k};`),
  'export default kit.default ?? kit.ZipkitNode;',
  '',
];

writeFileSync(path.join(root, 'node-esm.mjs'), lines.join('\n'));
console.log(`Generated node-esm.mjs with ${keys.length} named exports`);
